const { readFileSync, existsSync } = await import('node:fs');
const imagePath = globalThis.input.image_path;
if (!imagePath || !existsSync(imagePath)) {
  throw new Error('Input image_path missing or file does not exist');
}
const content = readFileSync(imagePath, 'utf8');
globalThis.imageBytes = Buffer.from(content, 'base64');
globalThis.imagePath = imagePath;

const mod = await import('pdf-lib-incremental-save');
const lib = mod.default || mod;
const { PDFDocument } = lib;
const pdfDoc = await PDFDocument.create();
const pngImage = await pdfDoc.embedPng(globalThis.imageBytes);
const page = pdfDoc.addPage();
const { width, height } = pngImage.scale(1);
page.drawImage(pngImage, { x: 0, y: 0, width, height });
const pdfBytes = await pdfDoc.save();
globalThis.pdfBase64 = Buffer.from(pdfBytes).toString('base64');
